import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s1-u12")

L(1, "O verbo em segundo lugar", "A regra mais importante da frase neerlandesa.",
  ["Pôr o verbo conjugado na segunda posição"],
  vocab=[V("v-vaak","vaak","muitas vezes|frequentemente","adverb"), V("v-soms","soms","às vezes","adverb"),
         V("v-altijd","altijd","sempre","adverb"), V("v-nooit","nooit","nunca","adverb")],
  ex=[("Ik drink vaak koffie.","Bebo café muitas vezes."),("Hij werkt altijd thuis.","Ele trabalha sempre em casa."),("Wij lezen soms de krant.","Às vezes lemos o jornal.")],
  gram=[G("g-v2","Verbo em 2.º lugar (V2)","Numa frase declarativa, o **verbo conjugado ocupa sempre a 2.ª posição**. A 1.ª posição pode ser o sujeito ou outro elemento. Advérbios como **vaak, soms, altijd, nooit** vêm normalmente **depois** do verbo: *ik drink **vaak** koffie*.",
    [("Ik werk altijd thuis.","Trabalho sempre em casa.")],
    "Em português dizemos «eu sempre trabalho» ou «trabalho sempre»; em neerlandês só a segunda ordem: «ik werk altijd».")],
  review=["v-drinken","v-werken","v-lezen","v-thuis"],
  exs=[
    MA([("vaak","muitas vezes"),("soms","às vezes"),("altijd","sempre"),("nooit","nunca")], "Advérbios de frequência.", ["v-vaak","v-soms","v-altijd","v-nooit"]),
    WO("Bebo café muitas vezes.", ["Ik","drink","vaak","koffie"], "Verbo em 2.º; advérbio depois do verbo.", ["v-vaak","v-drinken"]),
    WO("Ele trabalha sempre em casa.", ["Hij","werkt","altijd","thuis"], "werkt na 2.ª posição.", ["v-altijd","v-werken"]),
    FE(["Ik","altijd","drink","thee."], 1, "drink altijd", "O verbo tem de estar em 2.º: ik drink altijd thee.", ["v-altijd"]),
    MC("Qual é a ordem certa?", ["*Wij lezen soms de krant.","Wij soms lezen de krant.|O verbo tem de ser o 2.º elemento.","Soms wij lezen de krant.|Se a frase começa por «soms», o verbo vem logo a seguir."], "Sujeito + verbo + advérbio.", ["v-soms"]),
    TR("pt-nl","Nunca bebo leite.", ["Ik drink nooit melk"], "Advérbio depois do verbo.", ["v-nooit","v-melk"], bank=["Ik","drink","nooit","melk","niet"]),
    TR("nl-pt","Zij reist vaak naar Portugal.", ["(Ela )viaja muitas vezes para Portugal","(Ela )viaja frequentemente para Portugal"], "vaak = muitas vezes.", ["v-vaak","v-reizen"]),
    FB("Ik lees ___ een boek, maar niet vaak.", ["soms"], "soms = às vezes.", ["v-soms"], choices=["soms","nooit","altijd"], tr="Às vezes leio um livro, mas não muitas vezes."),
    LI("Hij komt altijd te laat.", ["Hij komt altijd te laat"], "Ele chega sempre atrasado.", "te laat = tarde demais / atrasado.", ["v-altijd","v-komen"]),
    WO("Às vezes durmo no sofá.", ["Ik","slaap","soms","op","de","bank"], "slaap na 2.ª posição.", ["v-soms","v-slapen"]),
  ], diff=2, mins=5)

L(2, "Inversão: começar por outra coisa", "Vandaag werk ik: quando o sujeito passa para depois do verbo.",
  ["Começar frases por tempo ou lugar mantendo o verbo em 2.º"],
  vocab=[V("v-nu-straks","straks","daqui a pouco|mais logo","adverb"), V("v-dan","dan","então|depois","adverb"),
         V("v-eerst","eerst","primeiro","adverb"), V("v-daarna","daarna","depois disso|a seguir","adverb")],
  ex=[("Vandaag werk ik thuis.","Hoje trabalho em casa."),("Morgen gaan we naar Utrecht.","Amanhã vamos a Utrecht."),("Eerst drink ik koffie, daarna lees ik de krant.","Primeiro bebo café, depois leio o jornal.")],
  gram=[G("g-inversao","Inversão","Se a frase **não começa pelo sujeito**, o sujeito passa para **depois do verbo**: *Ik werk vandaag* → ***Vandaag werk ik***. O verbo nunca sai da 2.ª posição. Com **jij/je** depois do verbo, o -t cai: *Morgen werk je thuis*.",
    [("Nu ga ik.","Agora vou."),("Daarna eet hij.","A seguir ele come.")],
    "Em português «Hoje eu trabalho» é normal; em neerlandês «Vandaag ik werk» está errado.")],
  review=["v-vandaag","v-morgen","v-nu","v-gaan","v-werken"],
  exs=[
    WO("Hoje trabalho em casa.", ["Vandaag","werk","ik","thuis"], "Começa por «vandaag» → verbo → sujeito.", ["v-vandaag","v-werken"], alt=["Ik werk vandaag thuis"]),
    WO("Amanhã vamos a Utrecht.", ["Morgen","gaan","we","naar","Utrecht"], "Morgen + verbo + sujeito.", ["v-morgen","v-gaan"], alt=["We gaan morgen naar Utrecht"]),
    FE(["Vandaag","ik","werk","thuis."], 1, "werk ik", "Depois de «vandaag» vem o verbo: vandaag werk ik.", ["v-vandaag"]),
    MC("Qual é a frase correta?", ["*Daarna lees ik de krant.","Daarna ik lees de krant.|Inversão: lees ik.","Daarna de krant ik lees.|O verbo tem de estar em 2.º."], "daarna + verbo + sujeito.", ["v-daarna"]),
    MA([("straks","daqui a pouco"),("dan","então"),("eerst","primeiro"),("daarna","depois disso")], "Ligar ações no tempo.", ["v-nu-straks","v-dan","v-eerst","v-daarna"]),
    TR("pt-nl","Agora vou para casa.", ["Nu ga ik naar huis","Ik ga nu naar huis"], "Nu + ga + ik.", ["v-nu","v-gaan"], bank=["Nu","ga","ik","naar","huis","gaat"]),
    TR("nl-pt","Eerst werk ik, daarna drink ik koffie.", ["Primeiro trabalho, depois bebo (um )café","Primeiro trabalho, a seguir bebo (um )café"], "Duas inversões.", ["v-eerst","v-daarna"]),
    CJ("werken","je","Morgen ___ je thuis.", ["werk"], "Inversão com je: o -t cai.", ["v-werken"]),
    FB("Straks ___ ik naar de supermarkt.", ["ga"], "Straks + verbo (ga) + ik.", ["v-nu-straks","v-gaan"], choices=["ga","ik ga","gaat"], tr="Daqui a pouco vou ao supermercado."),
    LI("Morgen gaan we naar het strand.", ["Morgen gaan we naar het strand"], "Amanhã vamos à praia.", "het strand = a praia.", ["v-morgen","v-gaan"]),
  ], diff=2, mins=6)

L(3, "Tempo, modo e lugar", "A ordem dos complementos: quando, como, onde.",
  ["Ordenar complementos de tempo, modo e lugar"],
  vocab=[V("v-met","met","com","preposition"), V("v-naar","naar","para|a","preposition",note="Direção: naar huis, naar Utrecht."),
         V("v-om","om","às (horas)","preposition",note="om acht uur = às oito horas."), V("v-uur","uur","hora","noun","het",note="«acht uur» (sem plural depois de número).")],
  ex=[("Ik ga morgen met de trein naar Amsterdam.","Amanhã vou de comboio para Amesterdão."),("Hij werkt om negen uur.","Ele trabalha às nove horas.")],
  gram=[G("g-tmp","Tempo – Modo – Lugar","Depois do verbo, os complementos seguem normalmente a ordem **tempo – modo – lugar**: *Ik ga **morgen** (tempo) **met de trein** (modo) **naar Amsterdam** (lugar)*. É uma tendência forte, não uma lei absoluta.",
    [("We eten vanavond thuis.","Jantamos hoje em casa."),("Ik fiets elke dag naar school.","Vou de bicicleta todos os dias para a escola.")],
    "Em português a ordem é mais livre («vou para Amesterdão amanhã de comboio»).")],
  review=["v-gaan","v-trein","v-fiets","v-morgen"],
  exs=[
    WO("Amanhã vou de comboio para Amesterdão.", ["Ik","ga","morgen","met","de","trein","naar","Amsterdam"], "tempo (morgen) – modo (met de trein) – lugar (naar Amsterdam).", ["v-met","v-naar"], alt=["Morgen ga ik met de trein naar Amsterdam"]),
    MA([("met","com"),("naar","para"),("om","às"),("uur","hora")], "Preposições úteis.", ["v-met","v-naar","v-om","v-uur"]),
    MC("Qual é a ordem mais natural?", ["*Ik ga vandaag met de fiets naar school.","Ik ga naar school met de fiets vandaag.|A tendência é tempo – modo – lugar.","Ik ga met de fiets vandaag naar school.|O tempo vem antes do modo."], "tempo – modo – lugar.", ["v-met"]),
    TR("pt-nl","Ele trabalha às nove.", ["Hij werkt om negen uur","Hij werkt om negen"], "om + número + uur.", ["v-om","v-uur"]),
    FB("Ik ga ___ de trein naar Utrecht.", ["met"], "met de trein = de comboio.", ["v-met"], choices=["met","naar","om"], tr="Vou de comboio para Utrecht."),
    FB("We gaan morgen ___ Rotterdam.", ["naar"], "naar = para (direção).", ["v-naar"], choices=["naar","met","in"], tr="Amanhã vamos para Roterdão."),
    FE(["Ik","kom","om","acht","uren."], 4, "uur", "Depois de um número: uur (singular).", ["v-uur"]),
    TR("nl-pt","We eten om zeven uur thuis.", ["(Nós )comemos às sete( horas) em casa","Jantamos às sete( horas) em casa"], "tempo (om zeven uur) – lugar (thuis).", ["v-om"]),
    LI("Ik fiets elke dag naar mijn werk.", ["Ik fiets elke dag naar mijn werk"], "Vou de bicicleta todos os dias para o trabalho.", "fietsen = andar de bicicleta.", ["v-naar"]),
    WO("Às oito vou a pé para a escola.", ["Om","acht","uur","loop","ik","naar","school"], "Começa pelo tempo → inversão.", ["v-om","v-lopen"], alt=["Ik loop om acht uur naar school"]),
  ], diff=3, mins=6)

L(4, "Frases com «en», «maar» e «want»", "Ligar duas frases sem mudar a ordem.",
  ["Ligar frases com en, maar, want, of"],
  vocab=[V("v-want","want","porque|pois","conjunction",note="Não altera a ordem: ik blijf thuis, want ik ben ziek."),
         V("v-of","of","ou","conjunction"), V("v-dus","dus","portanto|então","conjunction",note="Depois de «dus» o verbo vem logo a seguir: dus blijf ik thuis.")],
  ex=[("Ik ben moe, maar ik werk.","Estou cansado, mas trabalho."),("Ik blijf thuis, want ik ben ziek.","Fico em casa, porque estou doente."),("Koffie of thee?","Café ou chá?")],
  gram=[G("g-coordenadas","Conjunções coordenativas","**en, maar, want, of** ligam duas frases sem mudar a ordem: depois delas vem sujeito + verbo normalmente. **dus** é diferente: conta como 1.ª posição, por isso o verbo vem logo a seguir: *Ik ben ziek, **dus blijf ik** thuis*. (Na fala também se ouve «dus ik blijf», mas a forma padrão tem inversão.)",
    [("Het regent, dus neem ik de bus.","Está a chover, por isso apanho o autocarro.")],
    "«want» e «omdat» significam «porque», mas «omdat» manda o verbo para o fim (unidade de orações subordinadas).")],
  review=["v-en","v-maar","v-ziek","v-thuis","v-moe"],
  exs=[
    MA([("en","e"),("maar","mas"),("want","porque"),("of","ou"),("dus","portanto")], "Conjunções.", ["v-en","v-maar","v-want","v-of","v-dus"]),
    WO("Fico em casa, porque estou doente.", ["Ik","blijf","thuis,","want","ik","ben","ziek"], "want + ordem normal.", ["v-want","v-ziek"]),
    MC("Qual está correta?", ["*Ik ben ziek, dus blijf ik thuis.","Ik ben ziek, dus ik thuis blijf.|O verbo não vai para o fim.","Ik ben ziek, want blijf ik thuis.|Depois de «want» não há inversão."], "dus + verbo + sujeito.", ["v-dus"]),
    TR("pt-nl","Café ou chá?", ["Koffie of thee"], "of = ou.", ["v-of","v-koffie"]),
    TR("nl-pt","Ik ben moe, maar ik werk.", ["Estou cansad[o|a], mas trabalho","Estou cansad[o|a], mas estou a trabalhar"], "maar = mas.", ["v-maar","v-moe"]),
    FB("Ik neem de trein, ___ mijn fiets is kapot.", ["want"], "want = porque (ordem normal).", ["v-want"], choices=["want","dus","of"], tr="Apanho o comboio, porque a minha bicicleta está avariada."),
    FE(["Ik","ben","moe,","want","ben","ik","laat."], 4, "ik ben", "Depois de «want» não há inversão: want ik ben laat.", ["v-want"]),
    TR("pt-nl","Ela está doente, portanto fica em casa.", ["[Zij|Ze] is ziek(,) dus [blijft ze|blijft zij] thuis"], "dus provoca inversão.", ["v-dus","v-ziek"]),
    LI("Wil je koffie of thee?", ["Wil je koffie of thee"], "Queres café ou chá?", "of = ou.", ["v-of"]),
    CO("text","Uma manhã difícil", "Het is maandag en Eva is moe. Ze wil thuis blijven, maar ze moet werken. Ze neemt de bus, want het regent. Dus komt ze te laat op haar werk.",
       [("Porque apanha a Eva o autocarro?", ["*Porque está a chover","Porque está cansada","Porque é segunda-feira"]),("O que acontece no fim?", ["*Chega atrasada ao trabalho","Fica em casa","Vai de bicicleta"])],
       "want = porque; dus = portanto.", ["v-want","v-dus"]),
  ], diff=3, mins=6)

L(5, "Ordem das palavras: revisão", "V2, inversão, tempo-modo-lugar e conjunções.",
  ["Construir frases com a ordem correta"],
  ex=[("Vandaag ga ik met de bus naar mijn werk, want mijn fiets is kapot.","Hoje vou de autocarro para o trabalho, porque a minha bicicleta está avariada.")],
  review=["v-vaak","v-altijd","v-daarna","v-met","v-naar","v-want","v-dus","v-vandaag"],
  exs=[
    WO("Depois bebemos café.", ["Daarna","drinken","we","koffie"], "Inversão depois de «daarna».", ["v-daarna"], alt=["We drinken daarna koffie"]),
    WO("Ele lê sempre o jornal.", ["Hij","leest","altijd","de","krant"], "Advérbio depois do verbo.", ["v-altijd","v-lezen"]),
    FE(["Morgen","jij","werkt","thuis?"], 1, "werk jij", "Pergunta/inversão: Werk jij morgen thuis? / Morgen werk jij thuis.", ["v-morgen"]),
    MC("Qual é a ordem certa?", ["*Ik ga om acht uur met de fiets naar school.","Ik ga naar school met de fiets om acht uur.|Tempo – modo – lugar.","Om acht uur ik ga met de fiets naar school.|Inversão: om acht uur ga ik."], "tempo – modo – lugar.", ["v-om","v-met"]),
    TR("pt-nl","Hoje trabalho em casa, porque estou doente.", ["Vandaag werk ik thuis(,) want ik ben ziek","Ik werk vandaag thuis(,) want ik ben ziek"], "Inversão + want.", ["v-vandaag","v-want"]),
    TR("nl-pt","Soms lees ik een boek.", ["Às vezes leio um livro"], "Inversão depois de «soms».", ["v-soms"]),
    LI("Daarna gaan we naar huis.", ["Daarna gaan we naar huis"], "Depois vamos para casa.", "daarna + verbo + sujeito.", ["v-daarna"]),
    FB("Het regent, ___ neem ik de bus.", ["dus"], "dus provoca inversão: neem ik.", ["v-dus"], choices=["dus","want","maar"], tr="Está a chover, por isso apanho o autocarro."),
    CO("text","O sábado do Pedro", "Op zaterdag slaapt Pedro altijd lang. Daarna drinkt hij koffie en leest hij de krant. 's Middags fietst hij met zijn vriendin naar het strand.",
       [("O que faz o Pedro sempre ao sábado?", ["*Dorme até tarde","Trabalha","Vai ao supermercado"]),("Como vai à praia?", ["*De bicicleta","De comboio","A pé"])],
       "Repare nas inversões: daarna drinkt hij, 's middags fietst hij.", ["v-altijd","v-daarna"]),
    SW("Descreva a sua manhã com «eerst», «daarna» e «dan» (verbo em 2.º lugar!).", ["Eerst drink ik koffie(,) daarna [lees ik de krant|ga ik naar mijn werk]","Eerst [drink ik koffie|slaap ik](.) Daarna [ga ik|werk ik]"],
       ["Começa frases com «eerst», «daarna» ou «dan»","Depois dessas palavras vem o verbo e só depois «ik»"], 6, "Modelo: «Eerst drink ik koffie, daarna lees ik de krant en dan ga ik naar mijn werk.»", ["v-eerst","v-daarna"]),
  ], diff=3, mins=7)

W()
